-- Events in the shape of release v0.0.2.
CREATE OR REPLACE VIEW minio.opdi.events AS
SELECT
    event_id AS id,
    flight_id,
    type,
    event_time,
    longitude,
    latitude,
    altitude_ft AS altitude,
    source,
    version,
    info
FROM minio.opdi.flight_events;

-- Measurements in the shape of release v0.0.2: one row per measured value.
CREATE OR REPLACE VIEW minio.opdi.measurements AS
SELECT
    e.event_id || m.suffix AS id,
    e.event_id AS event_id,
    m.type AS type,
    m.value AS value,
    m.version AS version
FROM minio.opdi.flight_events AS e
CROSS JOIN UNNEST(
    ARRAY['Distance flown (NM)', 'Time Passed (s)', 'Holding duration (s)', 'Holding distance (NM)', 'Holding circuits', 'Point merge leg time (s)', 'Point merge leg distance (NM)', 'Point merge direct-to distance (NM)'],
    ARRAY['_d', '_t', '_ma46319', '_m9a9c44', '_m345087', '_m8dc3fb', '_m602fff', '_mead295'],
    ARRAY[e.distance_flown_nm, e.time_passed_s, e.holding_duration_s, e.holding_distance_nm, e.holding_circuits, e.pms_leg_time_s, e.pms_leg_distance_nm, e.pms_direct_to_distance_nm],
    ARRAY['distance_v0.0.3', 'time_v0.0.1', 'holding_v0.1.0', 'holding_v0.1.0', 'holding_v0.1.0', 'pms_v0.1.0', 'pms_v0.1.0', 'pms_v0.1.0']
) AS m (type, suffix, value, version)
WHERE m.value IS NOT NULL;

-- The flight list with the columns and names of release v0.0.2. Trino shows
-- every column name in lower case.
CREATE OR REPLACE VIEW minio.opdi.flight_list_v0 AS
SELECT
    flight_id AS ID,
    icao24 AS ICAO24,
    flt_id AS FLT_ID,
    dof AS DOF,
    adep AS ADEP,
    ades AS ADES,
    adep_p AS ADEP_P,
    ades_p AS ADES_P,
    registration AS REGISTRATION,
    model AS MODEL,
    typecode AS TYPECODE,
    icao_aircraft_class AS ICAO_AIRCRAFT_CLASS,
    icao_operator AS ICAO_OPERATOR,
    first_seen AS FIRST_SEEN,
    last_seen AS LAST_SEEN,
    version AS VERSION
FROM minio.opdi.flight_list;
